import fs from 'fs';
import path from 'path';
import chalk from 'chalk';
import { execSync } from 'child_process';
import { createHash } from 'crypto';
import { fileURLToPath } from 'url';
import { success, info, fatal } from '../utils/logger.js';
import { loadState, saveState } from '../core/state.js';
import { findProjectRoot } from '../core/project-root.js';
import { requireCurrentLayout } from '../core/workdir.js';
import {
  scaffoldEntries,
  templates,
  unplaceDescriptorPath,
} from '../core/project-layout.js';
import { CONFIG_FILE, CONFIG_FILE_JSONC, configFileName, stripJsonc } from '../core/project-config.js';
import { detectFrontend } from '../core/frontend.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const templatesDir = path.join(__dirname, '..', 'templates');

function sha256Hex(buffer) {
  return 'sha256:' + createHash('sha256').update(buffer).digest('hex');
}

// Content for a scaffolded file: the server-provided template, else the bundled
// copy; null when neither exists.
function templateContent(relPath, serverTemplates) {
  if (serverTemplates[relPath] != null) return serverTemplates[relPath];
  const bundled = path.join(templatesDir, unplaceDescriptorPath(relPath));
  return fs.existsSync(bundled) ? fs.readFileSync(bundled, 'utf-8') : null;
}

function readPackageJson() {
  try {
    return JSON.parse(fs.readFileSync('package.json', 'utf-8'));
  } catch {
    return null;
  }
}

const SCHEMA_REF = './node_modules/@tgcloud/cli/schema/tgcloud.json';

// Write a starter tgcloud.jsonc when the project has no config yet. With a
// recognized build folder the `static` block is live; otherwise it is left
// commented out. `immutable` is offered as a comment, never enabled.
// Every commented line is followed by a live one, so the file has no trailing
// comma as written and none after uncommenting. `$schema` is written only when
// the CLI is installed in the project, where the reference resolves.
function ensureProjectConfig(frontend) {
  if (fs.existsSync(CONFIG_FILE) || fs.existsSync(CONFIG_FILE_JSONC)) return false;
  const schema = fs.existsSync(SCHEMA_REF) ? `  "$schema": ${JSON.stringify(SCHEMA_REF)}` : null;
  const lines = ['{'];
  if (frontend?.source) {
    if (schema) lines.push(schema + ',');
    lines.push(
      '  "static": {',
      '    // Serve index.html for unknown paths (client-side routing):',
      '    // "spa": true,',
    );
    if (frontend.hashedAssets) {
      lines.push(
        `    // Let browsers cache content-hashed files for a year (${frontend.name} puts them here):`,
        `    // "immutable": ["${frontend.hashedAssets}"],`,
      );
    }
    lines.push(
      '    // The build output folder, hosted as the Mini App:',
      `    "source": ${JSON.stringify(frontend.source)}`,
      '  }',
    );
  } else {
    lines.push(
      '  // To host a Mini App, uncomment and set "source" to its build output folder:',
      '  // "static": {',
      '  //   "source": "dist"',
      schema ? '  // },' : '  // }',
    );
    if (schema) lines.push(schema);
  }
  lines.push('}');
  fs.writeFileSync(CONFIG_FILE_JSONC, lines.join('\n') + '\n');
  return true;
}

// Whether the project config deploys a static build. Never fails on a malformed config.
function managesStatic() {
  for (const file of [CONFIG_FILE, CONFIG_FILE_JSONC]) {
    if (!fs.existsSync(file)) continue;
    try {
      const text = fs.readFileSync(file, 'utf-8');
      const value = JSON.parse(file === CONFIG_FILE ? text : stripJsonc(text)).static;
      return typeof value === 'string' || (value != null && typeof value === 'object');
    } catch {
      return false;
    }
  }
  return false;
}

// Ensure package.json exists. An existing one only gains scripts (the whole
// block, or a `deploy` key when that name is free); other keys are never added
// and existing keys are never replaced. `deploy` builds first when a static
// build is deployed and a `build` script exists.
// Returns 'created' | 'updated' | null (unchanged or malformed).
function ensurePackageJson(staticManaged) {
  const existed = fs.existsSync('package.json');
  let pkg = { name: path.basename(process.cwd()), private: true };
  if (existed) {
    pkg = readPackageJson();
    if (!pkg || typeof pkg !== 'object' || Array.isArray(pkg)) return null; // malformed — leave it
  }
  let changed = false;
  const deploy = staticManaged && pkg.scripts?.build ? 'npm run build && tgcloud push' : 'tgcloud push';
  if (!('scripts' in pkg)) {
    pkg.scripts = { deploy, status: 'tgcloud status', run: 'tgcloud run' };
    changed = true;
  } else if (pkg.scripts && typeof pkg.scripts === 'object' && !('deploy' in pkg.scripts)) {
    pkg.scripts.deploy = deploy;
    changed = true;
  }
  if (!existed || changed) {
    fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
    return existed ? 'updated' : 'created';
  }
  return null;
}

// Print created files, plus created dirs that stayed empty, as a sorted ✓ list.
function printCreated(dirs, files) {
  const emptyDirs = dirs
    .filter((d) => !files.some((f) => f === d || f.startsWith(d + '/')))
    .map((d) => `${d}/`);
  const entries = [...files, ...emptyDirs].sort((a, b) => a.localeCompare(b));
  for (const e of entries) success(e);
}

// Best-effort git setup. Skipped inside an existing work tree: a nested
// `git init` would create an embedded repo. Otherwise init + add + commit as
// one step; if the commit fails, the new .git is removed.
function setupGit() {
  try {
    execSync('git rev-parse --is-inside-work-tree', { stdio: 'ignore' });
    info('Using the existing git repository.');
    return;
  } catch {
    // not inside a work tree — create a fresh repo below
  }

  try {
    execSync('git init', { stdio: 'ignore' });
  } catch {
    return; // git not installed
  }

  try {
    execSync('git add -A', { stdio: 'ignore' });
    execSync('git commit -m "Initial commit"', { stdio: 'ignore' });
    info('Initialized a git repository with an initial commit.');
  } catch {
    fs.rmSync('.git', { recursive: true, force: true });
    info('Skipped git — set your git user.name and user.email, then run "git init" yourself.');
  }
}

export function registerInit(program) {
  program
    .command('init')
    .description('Initialize a new tgcloud project (local scaffolding only)')
    .option('--no-git', 'Skip git repository initialization and the initial commit')
    .action(async (options) => {
      // Refuse to nest a project inside another; re-running in the same directory is fine.
      const existing = findProjectRoot();
      if (existing && path.resolve(existing) !== path.resolve(process.cwd())) {
        fatal(
          `Already inside a tgcloud project at ${existing}.\n` +
          `Run "tgcloud init" in a separate directory, or cd to that project to work on it.`
        );
      }
      // A pre-0.2.0 layout must be upgraded first.
      if (existing) requireCurrentLayout();

      // Scaffolded .js files, hashed into init_templates below.
      const scaffoldedFiles = [];
      const createdDirs = [];
      const createdFiles = [];

      // Directory entries end with "/"; file entries may be nested paths.
      const serverTemplates = templates();

      for (const entry of scaffoldEntries()) {
        if (entry.endsWith('/')) {
          const dir = entry.slice(0, -1);
          if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
          createdDirs.push(dir);
          continue;
        }
        if (fs.existsSync(entry)) continue;
        const content = templateContent(entry, serverTemplates);
        if (content == null) continue;
        const dir = path.dirname(entry);
        if (dir && dir !== '.') fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(entry, content);
        createdFiles.push(entry);
        // Only deployable modules (.js) are tracked in init_templates.
        if (entry.endsWith('.js')) scaffoldedFiles.push(entry);
      }

      const gitignoreContent = fs.readFileSync(path.join(templatesDir, 'gitignore'), 'utf-8');
      if (fs.existsSync('.gitignore')) {
        // `node_modules`, `/node_modules` and `node_modules/` count as the same entry.
        const norm = (line) => line.trim().replace(/^\/+|\/+$/g, '');
        const existing = fs.readFileSync('.gitignore', 'utf-8');
        const have = new Set(existing.split('\n').map(norm));
        const linesToAdd = gitignoreContent.split('\n').filter(
          (line) => line && !have.has(norm(line))
        );
        if (linesToAdd.length) {
          const suffix = existing.endsWith('\n') ? '' : '\n';
          fs.appendFileSync('.gitignore', suffix + linesToAdd.join('\n') + '\n');
        }
      } else {
        fs.writeFileSync('.gitignore', gitignoreContent);
      }
      createdFiles.push('.gitignore');

      // Before package.json: its `deploy` script depends on whether a static build is deployed.
      const frontend = detectFrontend(readPackageJson());
      const configCreated = ensureProjectConfig(frontend);
      if (configCreated) createdFiles.push(CONFIG_FILE_JSONC);
      const staticManaged = managesStatic();

      if (ensurePackageJson(staticManaged)) createdFiles.push('package.json');

      // Hashes of the scaffolded files; a re-run keeps existing entries and adds only new ones.
      const state = loadState();
      for (const file of scaffoldedFiles) {
        state.init_templates[file] = sha256Hex(fs.readFileSync(file));
      }
      saveState(state);
      createdFiles.push('.tgcloud/state.json');

      info('Creating a new tgcloud project...');
      printCreated(createdDirs, createdFiles);

      // Last, so the initial commit captures the full scaffold.
      if (options.git) setupGit();

      info('\nProject ready. The scaffolded files are a starting point — edit or delete as you like.');
      if (frontend && staticManaged) {
        info(`${frontend.name} front-end found: its build is deployed as the Mini App (${configFileName()} → "static"). ` +
          `"npm run deploy" builds it and pushes everything.`);
      } else if (frontend && !frontend.source) {
        info(`${frontend.name} front-end found. To deploy it as the Mini App, configure a static export ` +
          `and point "static" → "source" in ${configFileName()} at its output folder.`);
      }
      // Suppressed when create-bot delegates: it prints its own next steps.
      if (!process.env.TGCLOUD_VIA_CREATE && !process.env.TGCLOUD_INIT_QUIET_NEXT) {
        info('\nNext steps:');
        info(`  ${chalk.cyan('tgcloud login')}    ${chalk.dim('# link this project to a bot')}`);
        if (staticManaged) info(`  ${chalk.cyan('npm run deploy')}   ${chalk.dim('# build the Mini App and deploy everything')}`);
        else info(`  ${chalk.cyan('tgcloud push')}     ${chalk.dim('# deploy to the cloud')}`);
      }
    });
}
